// Entry foils name plausible but unsuccessful responses to the episode.
// Extension foils are genuine, narrower lessons fitting one episode only.
const themeRows = [
  { id: 'permission', entry: 'Lea took a ruler from Ben’s desk because he was outside. Ben returned and could not finish his chart. Next time Lea asked first, and Ben found a spare ruler for her.', harder: ['Lea took Ben’s ruler while he was outside, leaving him unable to finish his chart. Next time she asked, and he found her a spare.', 'Otter used Badger’s umbrella without asking. Badger searched for it in the rain. Later Otter asked to borrow it and agreed when to return it.'], key: 'Ask before using something that belongs to another person.', entryFoils: ['Use an absent person’s things while their seat is empty.', 'Finish your work quickly before returning a borrowed ruler.'], partials: ['Find a spare ruler before drawing a chart.', 'Agree when to return an umbrella you borrow.'] },
  { id: 'shared-space', entry: 'A model castle filled the classroom doorway. People bumped it when they entered. The builders moved it onto a side table, and people could walk through without touching it.', harder: ['A model castle blocked the classroom doorway and people bumped it. The builders moved it onto a side table.', 'At the reading corner, bags covered every seat. Rina put them on hooks, and children could sit down with their books.'], key: 'Leave shared spaces clear for the people who need them.', entryFoils: ['Ask people to step over a model in a doorway.', 'Build a taller castle so visitors can see it.'], partials: ['Put a large model on a table away from a doorway.', 'Hang bags on hooks to leave reading seats free.'] },
  { id: 'turn-taking', entry: 'Jem started down the slide before the child below had moved away. They nearly bumped. Jem waited for the bottom to clear on his next turn, and both children had room.', harder: ['Jem slid before the child below had moved away, and they nearly bumped. On his next turn he waited for a clear space.', 'At music club, two children struck the same drum at once and knocked sticks together. They agreed to play one short turn each.'], key: 'Wait for a clear turn when people share an activity.', entryFoils: ['Slide more quickly when someone is still at the bottom.', 'Choose a longer slide when the playground is busy.'], partials: ['Wait until the bottom of a slide is clear.', 'Take short turns when two players share a drum.'] },
  { id: 'fair-materials', entry: 'Oli took the whole sheet of gold stickers for his crown. His group had none left. He returned the sheet, and they divided the stickers before finishing everyone’s crowns.', harder: ['Oli took all the gold stickers, leaving his group none. He returned the sheet and they divided them.', 'At games club, May kept the board game for the whole session, leaving others no turn. Next time she agreed to pass it to another pair after ten minutes.'], key: 'Share what is available so everyone can take part.', entryFoils: ['Choose your favourite materials before the others arrive.', 'Complete one person’s crown before giving others materials.'], partials: ['Divide a sheet of stickers among the crown makers.', 'Agree when to pass a game to the next pair.'] },
  { id: 'returning-tools', entry: 'After using the magnifier, Sol left it in his coat. The nature group searched the shelf and could not start. Sol returned it to its labelled place, where the next group found it.', harder: ['Sol left the magnifier in his coat, and the nature group could not find it. He returned it to its labelled shelf.', 'Hana put a game counter in a pencil tin by mistake. The next players lacked a counter until she put it back in the game box.'], key: 'Return shared things to the place where others expect them.', entryFoils: ['Keep useful tools with you for the next activity.', 'Choose a different activity when a tool is missing.'], partials: ['Keep the magnifier on its labelled shelf.', 'Put game counters back in their own game box.'] },
  { id: 'owning-errors', entry: 'Ivo scattered the score cards and said the wind had done it. His friend began looking for a loose window. Ivo explained what had happened, and they put the cards back in order.', harder: ['Ivo blamed the wind after scattering the score cards. His friend looked for a loose window until Ivo explained the spill.', 'At a match, Mae wrote an extra goal for her team. She told the referee about her error, and the score was corrected before the next game.'], key: 'Explain your own mistake so it can be put right.', entryFoils: ['Look for another cause before telling anyone about a spill.', 'Put the cards away before anyone can check them.'], partials: ['Sort scattered score cards into their proper order.', 'Tell the referee when a recorded score needs changing.'] },
  { id: 'keeping-promises', entry: 'Noor promised to feed the class fish but joined a game and forgot. The teacher fed them. The next day Noor did the feeding job before joining the game and marked it on the chart.', harder: ['Noor forgot her promised fish-feeding job while playing. The next day she fed the fish before her game and marked the chart.', 'Finn promised to bring a banner but left it at home. For the next event he put the finished banner beside his school bag the night before.'], key: 'Plan how to carry out a job you have promised.', entryFoils: ['Choose a longer game before doing a classroom job.', 'Leave a feeding job for the person who notices it.'], partials: ['Feed the class fish before joining a game.', 'Put the event banner beside your bag the night before.'] },
  { id: 'fair-comparisons', entry: 'Two runners began from different lines. The nearer runner won, but nobody knew who was faster. They started again from one line and could compare their running.', harder: ['Two runners started from different lines, so their race did not show who was faster. They raced again from one line.', 'Bea measured how much two jugs held by filling them with cupfuls, but she used different-sized cups. She used the same cup for both jugs and counted the cupfuls again.'], key: 'Use the same conditions when making a fair comparison.', entryFoils: ['Give each runner a different starting place.', 'Compare runners by looking at the colour of their shoes.'], partials: ['Start runners from the same line when comparing speed.', 'Use the same cup when comparing how much jugs hold.'] },
  { id: 'check-assumptions', entry: 'Mara thought the plain paper bag was empty and nearly recycled it. She looked inside and found the missing puppet shoes. She put the shoes with the puppet before recycling the empty bag.', harder: ['Mara nearly recycled a plain bag because she thought it was empty. Looking inside revealed the missing puppet shoes.', 'At playtime, Ari thought a quiet newcomer wanted to be alone. Ari asked, and learned that the child wanted to play but did not know the rules.'], key: 'Check what is true before acting on a guess.', entryFoils: ['Judge what a bag holds by the pictures outside.', 'Recycle a closed bag before sorting the puppet clothes.'], partials: ['Look inside a bag before deciding it is empty.', 'Ask a quiet newcomer whether they want to join a game.'] },
  { id: 'resolve-disagreement', entry: 'Two builders pulled their cardboard bridge towards different tables. A joint came loose. They stopped, chose one place together and carried the bridge there side by side.', harder: ['Two builders pulled a bridge towards different tables and loosened a joint. They chose one place together before carrying it.', 'During a play, two children both began announcing the next scene. They paused, agreed which scenes each would announce and restarted without speaking over each other.'], key: 'Agree on a plan before working together.', entryFoils: ['Pull harder when a partner chooses another direction.', 'Move the bridge quickly before choosing its destination.'], partials: ['Choose one destination before carrying a model together.', 'Decide who will announce each scene in a play.'] },
  { id: 'recognise-limits', entry: 'Ren tried carrying a heavy crate alone and could not lift it clear of the floor. He asked a helper to carry the other end. Together they moved it onto the trolley.', harder: ['Ren could not lift a heavy crate alone, so he asked a helper to share its weight.', 'Tess promised to make twenty decorations in one evening but finished only two. For the next event she offered to make two, and the group divided the remaining work.'], key: 'Choose a manageable part and share work that is too much.', entryFoils: ['Keep the whole load when a crate is difficult to lift.', 'Choose a longer route to practise carrying a heavy crate.'], partials: ['Share the weight when a crate is too heavy to lift.', 'Offer a number of decorations you have time to finish.'] },
  { id: 'repairing-harm', entry: 'Ava pulled a shared picture book from beneath a pile and tore its cover. She showed the teacher the tear and helped attach a new cover. The book returned to the shelf.', harder: ['Ava tore the cover of a shared book. She helped the teacher attach a new cover before returning it.', 'Leo knocked over a class plant and broke its pot. He helped move the plant into a spare pot and cleaned up the fallen soil.'], key: 'Help repair the damage when something goes wrong.', entryFoils: ['Put a damaged book back before anyone sees the tear.', 'Choose another book while someone else repairs the first.'], partials: ['Attach a new cover when a shared book cover tears.', 'Move a plant into another pot when its pot breaks.'] },
  { id: 'let-others-learn', entry: 'Milo took over his sister’s puzzle whenever she paused. She had no chance to try a piece. He showed how to find an edge, then handed the pieces back and waited while she tried.', harder: ['Milo kept finishing his sister’s puzzle for her. He began showing one useful move, then handing the pieces back.', 'At music club, an older player played a beginner’s part as well as his own. He offered a starting cue instead, and the beginner played the short part herself.'], key: 'Give useful guidance while leaving another person a chance to try.', entryFoils: ['Finish a learner’s puzzle whenever they pause.', 'Keep the difficult pieces so a learner cannot choose them.'], partials: ['Show how to find an edge before returning puzzle pieces.', 'Give a beginning player a cue for their own part.'] },
  { id: 'losing-well', entry: 'When Kim lost, she pushed the board and scattered the pieces. Her friend stopped playing. Kim helped set it up again and asked for another game without changing the old result.', harder: ['Kim scattered the board after losing. She helped set it up and asked for another game without changing the result.', 'A runner refused to congratulate the winner after a race. Later he shook the winner’s hand and joined her for practice before the next race.'], key: 'Accept a result and keep treating other players kindly.', entryFoils: ['Change the old result before asking to play again.', 'Put the pieces away when another player wins.'], partials: ['Restore a scattered board before asking for another game.', 'Congratulate a winner and prepare for another race.'] },
  { id: 'try-a-role', entry: 'Eli refused to move scenery because he had never done it. At rehearsal he tried moving one light panel with a partner. He liked helping the scene change and chose that job for the play.', harder: ['Eli refused an unfamiliar scenery job, then tried moving one panel with a partner and enjoyed it.', 'At music club, May rejected the shaker because she had not played it before. She tried one short rhythm and asked to play it again with the song.'], key: 'Try an unfamiliar role before deciding it is not for you.', entryFoils: ['Choose only jobs you have done before.', 'Wait until the play ends before trying a scenery job.'], partials: ['Move one light panel to try a scenery job.', 'Try a short shaker rhythm before joining a song.'] },
  { id: 'ask-before-helping', entry: 'Una coloured the blank part of her friend’s drawing to help. Her friend had wanted to leave it white for snow. On the next drawing Una asked what was needed and held the paper instead.', harder: ['Una coloured a blank space that her friend wanted to leave white for snow. Next time she asked and held the paper instead.', 'Dad moved a model to tidy the table, but its maker was still arranging it. On the next visit he asked which part of the table could be cleared.'], key: 'Ask what help is wanted before changing someone’s work.', entryFoils: ['Fill a blank space before the artist notices it.', 'Choose your favourite colours for another person’s drawing.'], partials: ['Ask before colouring an unfinished part of a drawing.', 'Check which table space is free before moving a model.'] },
  { id: 'needs-before-extras', entry: 'The group decorated a cart while its loose wheel still wobbled. The cart could not carry their bags. They fixed the wheel first on the next cart, then added ribbons when it rolled properly.', harder: ['A group decorated a cart but left its loose wheel unfixed. The cart could not carry their bags until they repaired it.', 'For a birthday, Ari spent all his coins on wrapping paper and could not buy the card he needed. Next time he chose the card first and used the coins left over for wrapping paper.'], key: 'Make room for what is needed before adding extras.', entryFoils: ['Choose brighter decorations when a cart will not roll.', 'Fill a cart with bags before repairing its loose wheel.'], partials: ['Repair a loose wheel before decorating a working cart.', 'Buy a needed card before choosing extra wrapping paper.'] },
  { id: 'shared-supplies', entry: 'Hana left a tap dripping after filling a bowl. A helper showed her the growing puddle in the sink. Hana closed the tap fully, and the dripping stopped.', harder: ['Hana left a tap dripping, then closed it fully when a helper showed her.', 'At the craft table, Bo threw away large clean paper pieces after cutting small stars. He took the pieces back out and left them in a tray for another group’s drawings.'], key: 'Take care of useful supplies that other people share.', entryFoils: ['Leave a tap dripping for the next person’s bowl.', 'Use a bigger bowl instead of closing a dripping tap.'], partials: ['Close a tap fully after filling a bowl.', 'Keep clean paper pieces for another group to use.'] },
  { id: 'welcome-newcomers', entry: 'The group began a game without explaining it to a new child. She ran to the wrong end and stopped. They showed her the goal and played a slow round together before starting again.', harder: ['A new child ran the wrong way because the group had not explained their game. They showed her and practised a slow round.', 'In class, a new pupil stayed standing when a silent signal meant sit down. A partner showed what the signal meant before the next activity.'], key: 'Explain unfamiliar routines so a newcomer can take part.', entryFoils: ['Begin the next round before a newcomer understands the goal.', 'Choose a faster game when a newcomer runs the wrong way.'], partials: ['Practise a game’s goal with a child who is new.', 'Show a new pupil what a classroom signal means.'] },
  { id: 'clear-directions', entry: 'Tom told a visitor that the hall was “over there.” The visitor chose the wrong door. Tom named the blue door beside the stairs, and the visitor found the hall.', harder: ['Tom’s “over there” sent a visitor to the wrong door. Naming the blue door beside the stairs helped.', 'Mina sent a message asking for “the thing” from the cupboard. Her partner brought the wrong object until Mina asked for the red measuring jug on the lower shelf.'], key: 'Give specific details when another person needs to find something.', entryFoils: ['Repeat the same pointing words from farther away.', 'Ask a visitor to try each door in turn.'], partials: ['Name a door and its nearby landmark for a visitor.', 'Name an object and its shelf when asking for it.'] },
  { id: 'look-for-evidence', entry: 'Leila said a plant needed water because its leaves hung down. Dad asked her to touch the soil. It was already wet. They moved the pot out of the hot sun instead, and the leaves lifted later.', harder: ['Leila guessed that drooping leaves meant dry soil. Touching the wet soil led her to move the plant from the hot sun instead.', 'Arun called his hat lost when he found its peg empty. A notice said damp clothes had been moved to the drying rack. He checked the rack and found his hat.'], key: 'Look for evidence before deciding what a problem means.', entryFoils: ['Add more water before checking the soil in a pot.', 'Judge a plant’s soil only by looking at its leaves.'], partials: ['Check the soil before watering a drooping plant.', 'Check the drying notice before deciding a hat is lost.'] },
  { id: 'small-contributions', entry: 'Bea could not lift the large box and thought she could not help. She carried the loose lids while two others carried the box. The whole set reached the hall together.', harder: ['Bea could not lift a large box, so she carried its loose lids while others carried it.', 'At a display, Ren could not paint the large pictures and sat aside. He made clear name labels, and visitors could tell which group had made each picture.'], key: 'A smaller useful job can still help the whole group.', entryFoils: ['Wait beside a heavy box until every job is finished.', 'Keep trying to lift the largest part by yourself.'], partials: ['Carry loose lids when a box is too heavy for you.', 'Make name labels so visitors can identify display pictures.'] },
];

const themeEntryRationales = {
  permission: ['Confuses an owner’s absence with permission; Ben still needed his ruler.', 'Treats speed as permission; finishing quickly does not resolve taking the ruler without asking.'],
  'shared-space': ['Keeps the obstruction instead of leaving room for people to pass.', 'Confuses visibility with access; a taller castle still occupies the doorway.'],
  'turn-taking': ['Confuses moving quickly with having a clear space; the other child has not moved away.', 'Changes the slide rather than the waiting behaviour that prevented the bump.'],
  'fair-materials': ['Confuses choosing first with having a fair share; the other makers still need stickers.', 'Keeps all the materials for one maker instead of dividing them for the group.'],
  'returning-tools': ['Keeps a shared tool out of the place where its next users look.', 'Avoids the activity instead of correcting the misplaced tool that caused the problem.'],
  'owning-errors': ['Continues the search for an unrelated cause instead of explaining the known spill.', 'Hides the evidence rather than helping others put the scattered cards in order.'],
  'keeping-promises': ['Repeats the choice to play before carrying out the promised job.', 'Transfers the promised responsibility to whoever notices, rather than planning to do it.'],
  'fair-comparisons': ['Repeats the unequal starting conditions that made the result unclear.', 'Uses an irrelevant visible feature instead of comparing running under equal conditions.'],
  'check-assumptions': ['Uses the outside appearance instead of checking the bag’s actual contents.', 'Acts on the untested guess and risks discarding the puppet shoes.'],
  'resolve-disagreement': ['Repeats the opposing force that loosened the bridge joint.', 'Adds speed without settling the disagreement about where the bridge should go.'],
  'recognise-limits': ['Keeps the same unmanageable load instead of sharing its weight.', 'Changes the route without reducing or sharing the weight that Ren could not lift.'],
  'repairing-harm': ['Conceals the tear instead of helping restore the shared book.', 'Leaves the repair to someone else instead of contributing to putting the damage right.'],
  'let-others-learn': ['Repeats the takeover that removed the learner’s chance to try.', 'Withholds the materials needed for the learner’s own attempt.'],
  'losing-well': ['Rewrites a result rather than accepting it and restoring friendly play.', 'Ends play because another person won, rather than responding kindly to the result.'],
  'try-a-role': ['Treats unfamiliarity as proof that the new role will not suit the child.', 'Delays the trial until it can no longer help the current performance.'],
  'ask-before-helping': ['Treats an intentional white area as unfinished work without checking the artist’s plan.', 'Substitutes the helper’s colour choices for the artist’s intended drawing.'],
  'needs-before-extras': ['Changes decoration instead of fixing the wheel that prevents the cart working.', 'Adds a load before correcting the fault that prevents the cart carrying it.'],
  'shared-supplies': ['Leaves the unwanted dripping in place after the bowl is filled.', 'Changes the bowl without stopping the water that continues to drip.'],
  'welcome-newcomers': ['Starts again while the newcomer still lacks the information needed to join.', 'Changes the pace without explaining the goal that the newcomer did not know.'],
  'clear-directions': ['Repeats the vague words that did not identify the correct door.', 'Uses trial and error instead of supplying the identifying landmark that worked.'],
  'look-for-evidence': ['Acts on the original guess even though the soil is already wet.', 'Treats one visible symptom as proof of dry soil instead of checking the soil itself.'],
  'small-contributions': ['Misses the useful smaller carrying job that Bea was able to do.', 'Keeps attempting the unmanageable whole load instead of choosing a useful part.'],
};

function audio(role, text, choiceId) {
  return { role, text, path: (role === 'choice' ? getLedaWordAudioPath(text) : '') || getLedaInstructionAudioPath(text),
    required: true, ...(choiceId ? { choiceId, value: text } : {}) };
}

function copies({ id, skill, claim, band, passage, prompt, labels, features, proof, rationales, explanation }) {
  const family = `v8-comprehension:${skill}:${id}`;
  return ['reading', 'listening'].map(domainId => {
    const listening = domainId === 'listening';
    const sourceId = `mock.v8.comprehension.${domainId}.${skill}.${id}.b${band}`;
    const choices = labels.map((label, index) => ({ id: `c${index}`, label }));
    const requiredAudioCues = [audio('instruction', prompt)];
    if (listening) requiredAudioCues.push(audio('passage', passage), ...choices.map(choice => audio('choice', choice.label, choice.id)));
    return {
      id: sourceId, sourceItemId: sourceId, canonicalItemId: `mock.v8.comprehension.${skill}.${id}.b${band}`,
      contentVersion: 'literacy-mock-v8', skillId: listening ? `listen_${skill}` : skill, domainId,
      level: band === 2 || band === 5 ? 1 : 2, format: 'choice', sourceFormat: 'ORIGINAL_RETAKE_COMPREHENSION_V8',
      answerMode: 'exact', constructClaim: listening ? `listening_${claim}` : claim,
      prompt, passage, choices, answer: 'c0', targetWord: '', renderTargetText: false,
      image: '', imageAlt: '', requiredImagePaths: [], tutorialOnly: false,
      modality: domainId, evidenceModality: listening ? 'audio' : 'text',
      displayPassageDuringResponse: !listening, hideWrittenLabels: false,
      stimulusKey: passage.toLowerCase().normalize('NFKC'), canonicalPassageId: passage, exposureFamilyId: family,
      requiredAudioCues, requiredAudioPaths: [...new Set(requiredAudioCues.map(cue => cue.path).filter(Boolean))],
      mediaReady: requiredAudioCues.every(cue => Boolean(cue.path)),
      missingAudioCues: requiredAudioCues.filter(cue => !cue.path).map(({ role, text, choiceId }) => ({ role, text, ...(choiceId ? { choiceId } : {}) })),
      explanation, distractorRationales: { c1: rationales[0], c2: rationales[1] },
      difficultyEvidence: proof.key,
      taskDemand: { reviewed: true, operation: claim, features, choiceCount: 3,
        passageWordCount: passage.split(/\s+/).length, proof },
      sourceProvenance: { kind: 'original_literacy_guide_retake', file: FILE, sourceId, pairedFamily: family,
        originalAuthorship: 'Distinct supplied evidence and semantic scenario; no NWEA questions or illustrations reused.' },
      mediaDecision: { role: listening ? 'audio-only' : 'text-only', construct: listening ? `listening_${claim}` : claim,
        paths: [], constructReview: 'approved', answerNeutral: 'approved',
        reason: listening ? 'The exact recorded passage and choices supply the evidence. No answer-revealing illustration or written passage substitutes for listening.'
          : 'The complete printed passage supplies the evidence. Only the question is narrated; passage and choices remain independent reading.' },
    };
  });
}

export function buildLiteracyMockRetakeComprehension() {
  const result = [];
  for (const [id, claim, passage, prompt, labels] of detailRows) result.push(...copies({
    id, skill: 'key_details', claim, band: 2, passage, prompt, labels,
    features: { relevantBindings: 1, competingBindingRoles: 0 },
    proof: { key: `The supplied sentence explicitly identifies ${labels[0]} for the requested detail.`, evidence: [passage] },
    rationales: labels.slice(1).map(label => `The supplied sentence identifies ${labels[0]}, not ${label}, for the requested detail.`),
    explanation: `The passage says: ${passage}`,
  }));
  for (const [id, passage, labels] of temporalRows) result.push(...copies({
    id, skill: 'sequencing', claim: 'story_event_order', band: 3, passage, prompt: 'What happened first?', labels,
    features: { temporalLinks: 2, presentationConflicts: 1 },
    proof: { key: `${labels[0]} happens before ${labels[1]}, which happens before ${labels[2]}; the account opens by mentioning a later event.`,
      chronology: labels, temporalRelations: [{ before: 'c0', after: 'c1' }, { before: 'c1', after: 'c2' }],
      evidence: passage.match(/[^.!?]+[.!?]/g).map(sentence => sentence.trim()) },
    rationales: [`${labels[1]} occurs after ${labels[0]}, even though it occurs before the final event.`, `${labels[2]} occurs after the other two events; mention order is not event order.`],
    explanation: `The order is ${labels.join(', then ')}. Both before/after links support that order.`,
  }));
  for (const [id, passage, key, foil1, foil2, evidence] of mainIdeaRows) result.push(...copies({
    id, skill: 'main_idea', claim: 'mostly_about_info', band: 4, passage, prompt: 'What is this passage mostly about?', labels: [key, foil1, foil2],
    features: { requiredEvidenceParts: 2, competingTruePartialAccounts: 2 },
    proof: { key: `${key} It combines both evidence parts.`, evidence,
      foils: [`${foil1} is supported by the first evidence part but omits the second.`, `${foil2} is supported by the second evidence part but omits the first.`] },
    rationales: [`${foil1} is true, but covers only the first part of the passage.`, `${foil2} is true, but covers only the second part of the passage.`],
    explanation: `${key} The other choices each describe one true part rather than the connected account.`,
  }));
  for (const row of themeRows) for (const band of [5, 6]) {
    const passage = band === 5 ? row.entry : row.harder.join(' ');
    const rationales = band === 5
      ? themeEntryRationales[row.id]
      : row.partials.map((foil, index) => `“${foil}” is useful in episode ${index + 1}, but does not cover the different problem and correction in episode ${2 - index}.`);
    result.push(...copies({ id: row.id, skill: 'theme', claim: 'lesson_mistake_fixed', band, passage,
      prompt: 'What lesson best fits the whole story?', labels: [row.key, ...(band === 5 ? row.entryFoils : row.partials)],
      features: { episodesToIntegrate: band === 5 ? 1 : 2, ...(band === 6 ? { plausiblePartialLessons: 2 } : {}) },
      proof: { key: band === 5 ? `${row.key} This explains the change from the mistake to its correction.`
        : `${row.key} This applies to both different mistakes and their corrections.`,
      evidence: band === 5 ? [row.entry] : row.harder,
      ...(band === 6 ? { foils: rationales, partialLessons: row.partials } : {}) },
      rationales, explanation: band === 5 ? `${row.key} The changed action resolves the problem in the supplied story.`
        : `${row.key} Each narrower alternative fits only one of the two episodes.`,
    }));
  }
  return result;
}
